  qr_code:'QR-ALPHA',qr_purpose:'Receiving only',pdf_filename:'synthetic-request.pdf',show_pricing:false}};
const readWrites=(r:WriteRecord[],suffix:string)=>r.filter(x=>x.path.endsWith(suffix));

