    await expect(page).toHaveURL(/search=warehouse/);
    await expect(page).toHaveURL(/zone=Ambient/);
    await expect(page).not.toHaveURL(/location_id=/);
    await page.getByRole('button', { name: 'Clear Filters' }).click();
